messages.content:
Game edukasi pengelompokan hewan vertebrata dan invertebrata dengan tema cartoon dan tempo Normal. Asumsi: item air seperti ubur-ubur dan cumi-cumi dipakai sebagai jebakan untuk meluruskan miskonsepsi "semua hewan air adalah vertebrata".

```js
AISYS.defineGame({
  schema: 1, kit: "endless-runner",
  id: "vertebrata-run", title: "Lautan Tulang Belakang", seed: "vertebrata-01",
  theme: { preset: "cartoon" },

  learning: {
    subject: "Biologi",
    concept: "Pengelompokan hewan vertebrata dan invertebrata berdasarkan ada tidaknya tulang belakang",
    objectives: ["Mengelompokkan hewan ke vertebrata atau invertebrata dengan benar"],
    misconceptions: ["Semua hewan yang hidup di air adalah ikan (vertebrata)"],
    mode: "category",
    categories: [
      { id: "vertebrata",   label: "Vertebrata",   color: "#2F80ED" },
      { id: "invertebrata", label: "Invertebrata", color: "#E5484D" }
    ],
    items: [
      { id: "ikan-mas",   label: "Ikan mas",     category: "vertebrata",   explain: "Punya tulang belakang, termasuk kelompok ikan (Pisces)." },
      { id: "katak",      label: "Katak",        category: "vertebrata",   explain: "Amfibi bertulang belakang; hidup di dua alam." },
      { id: "merpati",    label: "Merpati",      category: "vertebrata",   explain: "Burung (Aves) yang memiliki tulang belakang." },
      { id: "kucing",     label: "Kucing",       category: "vertebrata",   explain: "Mamalia bertulang belakang yang menyusui anaknya." },
      { id: "ular",       label: "Ular",         category: "vertebrata",   explain: "Reptil bertulang belakang meski tubuhnya panjang dan melata." },
      { id: "ubur-ubur",  label: "Ubur-ubur",    category: "invertebrata", explain: "Hidup di air tapi tanpa tulang belakang; tubuhnya lunak." },
      { id: "cumi-cumi",  label: "Cumi-cumi",    category: "invertebrata", explain: "Moluska tanpa tulang belakang meski hidup di laut." },
      { id: "cacing",     label: "Cacing",       category: "invertebrata", explain: "Tubuhnya lunak dan tidak memiliki tulang belakang." },
      { id: "siput",      label: "Siput",        category: "invertebrata", explain: "Moluska bertubuh lunak tanpa tulang belakang." },
      { id: "belalang",   label: "Belalang",     category: "invertebrata", explain: "Serangga berkerangka luar, tanpa tulang belakang." }
    ],
    target: { rotateAfterCorrect: 5, bias: 0.5 }
  },

  player: { x: 220, w: 44, h: 56, gravity: 2400, jumpVelocity: 900, lives: 3, invulnerableSec: 1.2 },
  world:  { groundY: 600, speed: 360, maxSpeed: 720, accel: 6 },

  spawner: {
    interval: [0.9, 1.5],
    table: [
      { type: "hazard", id: "batu",  w: 44, h: 48, weight: 3 },
      { type: "hazard", id: "semak", w: 90, h: 24, weight: 2 },
      { type: "item", weight: 5, heights: ["ground", "mid", "high"] }
    ]
  },

  rules: {
    perSecond: 5,
    correct: { score: 50, sfx: "coin" },
    wrong:   { score: -20, sfx: "hit", showExplain: true },
    hazard:  { lives: -1, sfx: "hit", shake: 8 },
    combo:   { step: 5, max: 4 },
    difficulty: { everySec: 15, speed: 25 }
  }
});
// END_OF_MANIFEST
```
